    "      return true\n    }\n    return false\n  },\n  keys: func() {\n"
    "    return keys(db_data)\n  },\n  count: func() {\n    return len(db_data)\n  },\n"
    "  save: func() {\n    db_write()\n    return true\n  },\n  file: func() {\n"
    "    return db_file\n  }\n}\n\ndb_read()\n\n";
